import type { Task } from './philosophy-early-units-2026.ts';
import { task, W } from './philosophy-grade11-units-2026.ts';

// FEL.11.5 havuz genişletmesi: her bileşende mevcut 10 göreve 30 görev eklenir (düzey başına 6; toplam düzey başına 8, 11.4 ile aynı).
// Aynı vaka (Pınar / Tuna / Vildan), aynı kapsam sınırları: düşünür adı yok; ölüm, umutsuzluk ve ruhsal sıkıntı yok.
// Ölçütler düzey türüne göre ortaktır; her etiketin açıklaması sabittir.
const CU = [['Görüş ya da kavramın belirlenmesi (hayatın anlamı)', 'sorulan görüşü ya da kavramı panodaki sözlere uygun biçimde belirler'], ['Belirlemenin metne dayandırılması (hayatın anlamı)', 'belirlemesini panodaki sözlere ya da verdiği örneğe dayandırır'], ['Açık ve özgün yazım (hayatın anlamı)', 'yanıtı metni kopyalamadan, anlamı bozmadan açık cümlelerle yazar']] as [[string, string], [string, string], [string, string]];
const CA = [['Durumun doğru kavranması (hayatın anlamı)', 'verilen durumu ya da görüşü doğru anlayarak ele alır'], ['Görüşün ya da sorunun uygulanması (hayatın anlamı)', 'istenen görüşü, soruyu ya da ilkeyi duruma uygun biçimde uygular'], ['Uygulamanın tutarlılığı (hayatın anlamı)', 'uygulamayı görüşün kendi ölçütüyle çelişmeden tamamlar']] as [[string, string], [string, string], [string, string]];
const CN = [['Ögelerin ayrılması (hayatın anlamı)', 'öncül, iddia, gerekçe ya da ölçüt gibi ögeleri doğru ayırır'], ['Varsayım ya da boşluğun gösterilmesi (hayatın anlamı)', 'görüşün ya da argümanın dayandığı varsayımı ya da temellendirme boşluğunu gösterir'], ['Çözümlemenin gerekçelendirilmesi (hayatın anlamı)', 'çözümlemesini panodaki sözlere dayanarak gerekçelendirir']] as [[string, string], [string, string], [string, string]];
const CE = [['Yargının açıkça belirtilmesi (hayatın anlamı)', 'değerlendirme sorusuna açık bir yargı verir'], ['Gerekçenin görüşe dayandırılması (hayatın anlamı)', 'yargısını görüşün kendi iddiasına ya da bir örneğe dayanarak gerekçelendirir'], ['Karşı noktanın hesaba katılması (hayatın anlamı)', 'yargısına yöneltilebilecek bir karşı noktaya değinir']] as [[string, string], [string, string], [string, string]];
const CC = [['Özgün ürünün yazılması (hayatın anlamı)', 'istenen ürünü (durum, soru, argüman, diyalog, paragraf) özgün biçimde yazar'], ['Ürünün göreve uygunluğu (hayatın anlamı)', 'ürünün görevde istenen görüş, kavram ya da soruyla ilgisini gösterir'], ['Ürünün tutarlılığı (hayatın anlamı)', 'ürünü kendi içinde ve panodaki görüşlerle çelişmeden kurar']] as [[string, string], [string, string], [string, string]];
const u = (s: string, k: string): Task => task('understand', s, k, ...CU);
const a = (s: string, k: string): Task => task('apply', s, k, ...CA);
const n = (s: string, k: string): Task => task('analyze', s, k, ...CN);
const e = (s: string, k: string): Task => task('evaluate', s, k, ...CE);
const c = (s: string, k: string): Task => task('create', s, k, ...CC);

